import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),i={name:"guide/faq.md"};function s(n,e,l,d,h,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Frequently asked questions about Weeabooify.</p><h2 id="is-my-device-supported" tabindex="-1">Is my device supported? <a class="header-anchor" href="#is-my-device-supported" aria-label="Permalink to &quot;Is my device supported?&quot;">​</a></h2><p>Weeabooify supports <strong>Pixel devices</strong> and <strong>AOSP-based custom ROMs</strong>.</p><p>The following are <strong>not supported</strong>:</p><ul><li>MIUI / HyperOS (Xiaomi)</li><li>OneUI (Samsung)</li><li>OxygenOS (OnePlus)</li><li>ColorOS (OPPO/Realme)</li><li>iOS</li></ul><h2 id="what-is-anti-entropy-ae" tabindex="-1">What is Anti-Entropy (AE)? <a class="header-anchor" href="#what-is-anti-entropy-ae" aria-label="Permalink to &quot;What is Anti-Entropy (AE)?&quot;">​</a></h2><p><strong>Anti-Entropy (AE)</strong> is the primary variant of Weeabooify targeting <strong>Android 12 and above</strong>.</p><p>The other variant, <strong>Schicksal</strong>, targets Android 10 and uses the Substratum overlay engine. Each variant is sold separately.</p><h2 id="i-m-on-android-15-or-below-which-version-should-i-use" tabindex="-1">I&#39;m on Android 15 or below, which version should I use? <a class="header-anchor" href="#i-m-on-android-15-or-below-which-version-should-i-use" aria-label="Permalink to &quot;I&#39;m on Android 15 or below, which version should I use?&quot;">​</a></h2><p>Use <strong>version 5.6</strong> if you&#39;re on Android 15 or below. The latest release targets Android 16 QPR0.</p><h2 id="i-already-paid-—-what-do-i-do-next" tabindex="-1">I already paid — what do I do next? <a class="header-anchor" href="#i-already-paid-—-what-do-i-do-next" aria-label="Permalink to &quot;I already paid — what do I do next?&quot;">​</a></h2><ol><li>Contact <a href="https://t.me/kaerushi" target="_blank" rel="noreferrer">@KaeruShi</a> on Telegram</li><li>Send your <strong>payment screenshot</strong> as proof</li><li>You&#39;ll receive installation access and instructions</li></ol><h2 id="is-there-a-trial-version" tabindex="-1">Is there a Trial Version? <a class="header-anchor" href="#is-there-a-trial-version" aria-label="Permalink to &quot;Is there a Trial Version?&quot;">​</a></h2><p>Yes! The Trial Version is free and lets you test compatibility on your device before purchasing. It includes limited access to selected features. You can upgrade to the PRO Version at any time.</p><h2 id="does-it-work-without-root" tabindex="-1">Does it work without root? <a class="header-anchor" href="#does-it-work-without-root" aria-label="Permalink to &quot;Does it work without root?&quot;">​</a></h2><p>No. Weeabooify requires root access (via Magisk, KernelSU, SukiSU, or APatch) and the LSPosed framework to function.</p><h2 id="will-this-void-my-warranty" tabindex="-1">Will this void my warranty? <a class="header-anchor" href="#will-this-void-my-warranty" aria-label="Permalink to &quot;Will this void my warranty?&quot;">​</a></h2><p>Rooting your device typically voids the manufacturer warranty. By using Weeabooify, you acknowledge the risks. See the <a href="/legal/terms.html">Terms &amp; Conditions</a> for the full disclaimer.</p>',19)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
